const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');const {validateProfile}=require('../../../lib/protocol');const {runProfile,makeCanonicalResult,bounded}=require('../../../lib/runner');const {resolveExecutable}=require('../../../lib/runtime');function input(n){return process.env[`INPUT_${n.toUpperCase().replaceAll('-','_')}`]}function out(k,v){fs.appendFileSync(process.env.GITHUB_OUTPUT,`${k}=${v}\n`)}function spawn(exe,argv,o){return new Promise((resolve,reject)=>{exe=resolveExecutable(exe);const c=cp.spawn(exe,argv,{cwd:o.cwd,shell:false,windowsHide:true});let so='',se='',done=false,timedOut=false;const t=setTimeout(()=>{timedOut=true;o.killTree?.(c.pid);},o.timeoutMs);c.stdout?.on('data',d=>so=bounded(so+d.toString(),8192));c.stderr?.on('data',d=>se=bounded(se+d.toString(),8192));c.on('error',reject);c.on('close',(code,signal)=>{if(done)return;done=true;clearTimeout(t);resolve({exitCode:code??1,stdout:so,stderr:se,timedOut})})})}
(async()=>{const req=JSON.parse(input('request-json')),target=path.resolve(input('target-dir')),pdir=path.resolve(input('profile-dir')),odir=path.resolve(input('output-dir'));fs.mkdirSync(odir,{recursive:true});const pbytes=fs.readFileSync(path.join(pdir,`${req.profile.id}.json`)),profile=validateProfile(pbytes);const adapters={getHead:async d=>cp.execFileSync('git',['-C',d,'rev-parse','HEAD'],{encoding:'utf8'}).trim(),spawn,killTree:pid=>{try{if(process.platform==='win32')cp.execFileSync('taskkill.exe',['/PID',String(pid),'/T','/F'],{stdio:'ignore',windowsHide:true});else process.kill(pid,'SIGTERM')}catch{}},nowMs:()=>Date.now(),readFile:async f=>{const st=await fs.promises.stat(f);if(st.size>1048576)throw new Error('TEST_RESULT_TOO_LARGE');return fs.promises.readFile(f,'utf8')}};const free=()=>{const x=fs.statfsSync(target);return x.bavail*x.bsize/1073741824};const freeBefore=free(),startedAt=new Date().toISOString(),startedMs=Date.now();const r=await runProfile({requestedSha:req.target.sha,targetDir:target,profile},adapters);const finishedAt=new Date().toISOString(),freeAfter=free();const identity={request:req,requestCommentId:Number(input('request-comment-id')),requestBodySha256:input('request-body-sha256'),executionRepo:process.env.GITHUB_REPOSITORY,runId:process.env.GITHUB_RUN_ID,runAttempt:process.env.GITHUB_RUN_ATTEMPT,runUrl:`https://github.com/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID}`,workflowSha:process.env.GITHUB_SHA,containingBranch:input('containing-branch'),branchHeadAtAdmission:input('branch-head-at-admission')};fs.writeFileSync(path.join(odir,'identity.json'),JSON.stringify(identity));fs.writeFileSync(path.join(odir,'outcome.json'),JSON.stringify(r.outcome));if(r.kind==='refusal')fs.writeFileSync(path.join(odir,'refusal.marker'),'CHECKOUT_SHA_MISMATCH\n');if(r.kind==='canonical'){const result=makeCanonicalResult({...identity,runner:JSON.parse(input('runner-json')),timing:{admitted_at:input('admitted-at'),started_at:startedAt,finished_at:finishedAt,phases:[{name:'execute',duration_s:Math.max(0,(Date.now()-startedMs)/1000)}]},disk:{free_before_gib:freeBefore,free_after_gib:freeAfter,reserve_gib:Number(input('disk-reserve-gib'))}},r);fs.writeFileSync(path.join(odir,'result.json'),JSON.stringify(result))}out('execution-status',r.outcome.status)})().catch(e=>{console.error(e);process.exitCode=1});
